import React, { useState } from 'react';
import axios from 'axios';

interface UploadSlipPopupProps {
  id: string;
  onClose: () => void;
}

const UploadSlipPopup: React.FC<UploadSlipPopupProps> = ({ id, onClose }) => {
  const [file, setFile] = useState<File | null>(null);
  const [loading, setLoading] = useState(false);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      setFile(e.target.files[0]);
    }
  };

  const handleSubmit = async () => {
    if (!file) return;

    const formData = new FormData();
    formData.append('image', file);

    setLoading(true);
    try {
      const response = await axios.post(
        `http://localhost:5160/api/QrCode/${id}/upload-and-read`,
        formData,
        {
          headers: {
            'Content-Type': 'multipart/form-data',
            Accept: '*/*',
          },
        }
      );
      console.log('Upload success:', response.data);
      alert('อัปโหลดสำเร็จ');
      onClose();
    } catch (error) {
      console.error('Upload error:', error);
      alert('เกิดข้อผิดพลาดในการอัปโหลด');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="popup">
      <div className="popup-content">
        <h3>อัปโหลดสลิปชำระเงิน (ID: {id})</h3>
        <input type="file" accept="image/*" onChange={handleFileChange} />
        <button onClick={handleSubmit} disabled={loading || !file}>
          {loading ? 'กำลังอัปโหลด...' : 'อัปโหลด'}
        </button>
        <button onClick={onClose}>ปิด</button>
      </div>
    </div>
  );
};

export default UploadSlipPopup;
